fn main() {
    // Cutting tools used in today's milling job
    let mut tool_rack: Vec<&str> = Vec::new();

    // push() adds a value at the end of the vector
    tool_rack.push("roughing end mill");
    tool_rack.push("finishing end mill");
    tool_rack.push("spot drill");

    // len() counts items, is_empty() checks for zero
    println!("{} tools on the rack", tool_rack.len());
    println!("Rack empty? {}", tool_rack.is_empty());

    // pop() removes the last item and returns it as Option<&str>
    if let Some(put_away) = tool_rack.pop() {
        println!("Put away: {}", put_away);
    }
    println!("{} left: {:?}", tool_rack.len(), tool_rack);
}

fn main() {
    let mut speeds: Vec<u32> = Vec::new();
    speeds.push(800); // roughing pass
    speeds.push(1200);
    speeds.push(2400); // finishing pass

    // insert() places a value at an index, shifting the rest right
    speeds.insert(1, 1000);
    println!("{:?}", speeds); // [800, 1000, 1200, 2400]

    // remove() takes a value back out and returns it
    let dropped = speeds.remove(1);
    println!("dropped {}", dropped); // dropped 1000

    // get() returns Option — None when the index does not exist
    println!("{:?}", speeds.get(2)); // Some(2400)
    println!("{:?}", speeds.get(9)); // None
}

fn calculate_machining_time(parts: u32, time_per_part: f64) -> f64 {
    parts as f64 * time_per_part
}

fn main() {
    let turning_time = calculate_machining_time(20, 4.5);
    let milling_time = calculate_machining_time(15, 8.2);

    println!("Turning time: {:.2} minutes", turning_time);
    println!("Milling time: {:.2} minutes", milling_time);
}

