impl CuttingTool {
    fn new(name: &str, material: &str, sharpness: u8) -> CuttingTool {
        CuttingTool {
            name: name.to_string(),
            material: material.to_string(),
            sharpness,
        }
    }

    fn is_sharp(&self) -> bool {
        self.sharpness > 6
    }
}

