fn parse_rpm(input: &str) -> Result<u32, &str> {
    match input.parse() {
        Ok(num) => Ok(num),
        Err(_) => Err("Invalid RPM format"),
    }
}

fn main() {
    // Result has Ok(success value) or Err(error value)
    match parse_rpm("1200") {
        Ok(rpm) => println!("Spindle speed: {} RPM", rpm),
        Err(msg) => println!("Error: {}", msg),
    }
}

