fn main() {
    let shop_items: Vec<&str> = vec![
        "end mill", "wrench", "drill bit", "hammer", "reamer"
    ];

    // partition splits into two groups based on condition
    // matches! checks if value equals any of the patterns
    let (cutting, hand_tools): (Vec<&str>, Vec<&str>) = shop_items
        .into_iter()
        .partition(|&item| {
            matches!(item, "end mill" | "drill bit" | "reamer" | "tap")
        });

    println!("Cutting tools: {:?}", cutting);
    println!("Hand tools: {:?}", hand_tools);
}

struct ToolBox<T> {
    contents: Vec<T>,
}

impl<T> ToolBox<T> {
    fn new() -> Self {
        ToolBox {
            contents: Vec::new(),
        }
    }

    fn add(&mut self, item: T) {
        self.contents.push(item);
    }
}

