fn describe_tool(item: &str) {
    let description = match item {
        // match guards: extra conditions after 'if'
        tool if tool.ends_with("mill") => "This is a milling tool!",
        bit if bit.contains("drill") => "Drilling tool!",
        "caliper" => "Measuring tool for precision!",
        "micrometer" => "Ultra-precise measuring tool!",
        _ => "Essential workshop tool!",
    };

    println!("{}: {}", item, description);
}
